13	// 原文件保持原样。
14	func TestOpenRejectsFreezeMissingOriginInfo(t *testing.T) {
15		freeze := func(id, attrs string) string {
16			return `{"id":"` + id + `"` + attrs + `,"released":false}`
17		}
