1	package retention
2	
3	import (
4		"fmt"
5	)
6	
7	// validateBatchInputs 校验一批销毁/核对请求共有的输入：
8	// 申请编号、处理日期、非空且去空白后无重复的档案名单。
9	// 返回去首尾空白后的申请编号、按提交顺序规范化的名单及名单集合。
10	// 任一输入无效即返回错误，调用方不得据此产生部分结果。
11	func validateBatchInputs(applicationID string, processedOn Date, rawIDs []string) (string, []string, map[string]struct{}, error) {
12		appID, err := requireText(applicationID, "申请编号")
13		if err != nil {
14			return "", nil, nil, err
15		}
16		if err := requireDate(processedOn, "处理日期"); err != nil {
17			return "", nil, nil, err
18		}
19		if len(rawIDs) == 0 {
20			return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单为空: %w",
21				appID, ErrEmptyDestructionList)
22		}
23	
24		// 规范化名单并检查名单内重复（输入校验先于任何业务判断）。
25		// 同一编号仅因首尾空白不同也视为重复。
26		ids := make([]string, 0, len(rawIDs))
27		for _, raw := range rawIDs {
28			id, err := requireText(raw, "档案编号")
29			if err != nil {
30				return "", nil, nil, err
31			}
32			ids = append(ids, id)
33		}
34		seen := make(map[string]struct{}, len(ids))
35		for _, id := range ids {
36			if _, dup := seen[id]; dup {
37				return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单中档案 %s 重复: %w",
38					appID, id, ErrDuplicateSelection)
39			}
40			seen[id] = struct{}{}
41		}
42		return appID, ids, seen, nil
43	}
44	
45	// evaluateArchive 按当前保存状态核对一份档案在给定处理日期下的全部销毁阻碍，
46	// 是只读核对（Check）与正式销毁（Destroy）共用的同一份业务规则：
47	// 到期以当前生效的保管截止日（含修订后的日期）为准，处理日期不早于截止日即到期；
48	// 任一未解除冻结都是阻碍，已解除记录只保留在历史中。
49	//
50	// 阻碍按固定顺序列出：不存在、已销毁、未到期，然后是每条未解除冻结各一条
51	// （沿用冻结登记顺序）。已销毁的档案只带已销毁阻碍，并附所属清册的申请编号
52	// 和处理日期；不存在的编号只带不存在阻碍。返回结果同时携带登记内容，
53	// 供核对报告展示，也供正式销毁在失败时定位档案。
54	func evaluateArchive(data *storeData, id string, processedOn Date) ArchiveCheckResult {
55		r := ArchiveCheckResult{ID: id, Obstructions: []CheckObstruction{}}
56		ar, ok := data.Archives[id]
57		if !ok {
58			r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionMissing})
59			return r
60		}
61		r.Exists = true
62		r.Category = ar.Category
63		r.Start = ar.Start
64		r.End = ar.End
65		r.Destroyed = ar.Destroyed
66	
67		if ar.Destroyed {
68			// 已销毁档案给出所属清册的申请编号和处理日期。
69			obs := CheckObstruction{Kind: ObstructionDestroyed}
70			if rec, ok := data.Manifests[ar.ManifestID]; ok {
71				obs.ManifestApplicationID = rec.ApplicationID
72				// 通过校验的已关闭清册必然带有有效处理日期。
73				if rec.ProcessedOn != nil {
74					obs.ProcessedOn = *rec.ProcessedOn
75				}
76			} else {
77				obs.ManifestApplicationID = ar.ManifestID
78			}
79			r.Obstructions = append(r.Obstructions, obs)
80			return r
81		}
82	
83		// 未到期与未解除冻结可能同时成立，两类问题都要列出。
84		if processedOn.Before(ar.End) {
85			r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionNotExpired})
86		}
87		// 每条未解除冻结各成一条阻碍，顺序沿用冻结历史（登记顺序）。
88		for _, f := range ar.Freezes {
89			if f.Released {
90				continue
91			}
92			info := ActiveFreezeInfo{
93				FreezeID: f.ID,
94				Reason:   f.Reason,
95			}
96			// 通过校验的冻结必然带有有效冻结日期；防御性保留零值兜底。
97			if f.FrozenOn != nil {
98				info.FrozenOn = *f.FrozenOn
99			}
100			r.Obstructions = append(r.Obstructions, CheckObstruction{
101				Kind:   ObstructionActiveFreeze,
102				Freeze: info,
103			})
104		}
105		return r
106	}
107	
108	// firstObstructionError 把共用核对结果中的第一条阻碍转换为正式销毁的失败错误。
109	// 阻碍顺序固定（不存在、已销毁、未到期、未解除冻结），因此同一档案同时存在
110	// 多个问题时，错误类别与定位信息与既有判断先后一致。
111	func firstObstructionError(r ArchiveCheckResult, processedOn Date) error {
112		switch obs := r.Obstructions[0]; obs.Kind {
113		case ObstructionMissing:
114			return fmt.Errorf("retention: 档案 %s 不存在: %w", r.ID, ErrNotFound)
115		case ObstructionDestroyed:
116			return fmt.Errorf("retention: 档案 %s 已在清册 %s 中，不能再次销毁: %w",
117				r.ID, obs.ManifestApplicationID, ErrArchiveAlreadyOnManifest)
118		case ObstructionNotExpired:
119			return fmt.Errorf("retention: 档案 %s 尚未到期（截止日 %s，处理日期 %s）: %w",
120				r.ID, r.End, processedOn, ErrNotExpired)
121		case ObstructionActiveFreeze:
122			return fmt.Errorf("retention: 档案 %s 有未解除的冻结 %s: %w",
123				r.ID, obs.Freeze.FreezeID, ErrActiveFreeze)
124		}
125		return nil
126	}
127	
128	// Check 在正式办理销毁前做一次只读核对。
129	//
130	// 调用者提交申请编号、处理日期和档案编号名单，得到整批申请能否办理的报告，
131	// 一次看清所有阻碍。核对不销毁档案、不生成或改写清册，也不占用申请编号；
132	// 核对后（无论报告结论如何，甚至读取本地记录失败）仍可沿用同一编号继续
133	// 核对或正式提交。
134	//
135	// 报告区分四种结论：
136	//   - CheckReady 可以办理：申请编号尚未成功使用，名单中每份档案均无阻碍；
137	//   - CheckBlocked 存在阻碍：申请编号尚未成功使用，至少一份档案存在阻碍，
138	//     Results 按提交顺序列出每份档案的核对结果和全部适用阻碍；
139	//   - CheckReplayable 可以取回原清册：申请编号已成功使用，且日期与档案集合
140	//     （顺序无关）与原申请相同，Manifest 返回原清册，不因档案已销毁而判受阻；
141	//   - CheckConflict 申请编号冲突：沿用该编号但改变了日期或集合，Manifest 附原清册。
142	//
143	// 申请编号已被本保管库内任意一条成功的期限修订占用时（与本次选中的档案无关，
144	// 该档案后来再次修订或已销毁都不释放编号），整次核对明确失败，返回
145	// ErrRevisionConflict，报告为空——不列出逐份档案结果，也不附清册。
146	// 只有成功修订才占用编号；失败过的修订提交不影响核对。
147	//
148	// 到期与冻结判断与 Destroy 共用同一份实现（evaluateArchive）：处理日期达到
149	// 截止日当天即到期，任一未解除冻结都会阻止销毁，已解除记录不作为阻碍。
150	//
151	// 申请编号或任一档案编号为空白、日期缺失或不是真实的 YYYY-MM-DD、
152	// 名单为空或含重复编号时，整次核对明确失败，不返回部分报告；
153	// 读取本地记录失败同样明确失败，绝不会用旧报告充当本次结果。
154	//
155	// 报告中的档案结果与清册来自同一次已保存状态读取；报告只说明核对当时的
156	// 情况，之后状态若变化，正式提交仍按最新状态判断。返回值是复制生成的
157	// 只读视图，调用者修改报告或其中清册不影响已保存的历史。
158	func (s *Store) Check(req CheckRequest) (CheckReport, error) {
159		appID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
160		if err != nil {
161			return CheckReport{}, err
162		}
163	
164		var report CheckReport
165		err = s.view(func(data *storeData) error {
166			report = CheckReport{
167				ApplicationID: appID,
168				ProcessedOn:   req.ProcessedOn,
169				Results:       make([]ArchiveCheckResult, 0, len(ids)),
170			}
171	
172			// 申请编号已成功使用：只判断能否取回原清册或编号冲突，两者都附原清册。
173			// 原清册取自当前这一次状态读取，与下面逐份核对看到的记录同源。
174			if existing, ok := data.Manifests[appID]; ok {
175				m := manifestFromRecord(existing)
176				report.Manifest = &m
177				if sameApplication(existing, req.ProcessedOn, seen) {
178					report.Status = CheckReplayable
179				} else {
180					report.Status = CheckConflict
181				}
182				return nil
183			}
184	
185			// 申请编号已被任意一条成功的期限修订占用：整次核对失败，报告为空。
186			// 编号占用属于整个保管库，与本次选中的档案无关；失败过的修订不占用编号。
187			if _, rec := findRevision(data, appID); rec != nil {
188				return fmt.Errorf("retention: 申请编号 %s 已用于期限修订: %w",
189					appID, ErrRevisionConflict)
190			}
191	
192			// 申请编号尚未成功使用：按提交顺序逐份核对，每份列出全部适用阻碍。
193			// 核对规则与正式销毁共用 evaluateArchive，两处结论必然一致。
194			anyBlocked := false
195			for _, id := range ids {
196				r := evaluateArchive(data, id, req.ProcessedOn)
197				if len(r.Obstructions) > 0 {
198					anyBlocked = true
199				}
200				report.Results = append(report.Results, r)
201			}
202	
203			if anyBlocked {
204				report.Status = CheckBlocked
205			} else {
206				report.Status = CheckReady
207			}
208			return nil
209		})
210		if err != nil {
211			return CheckReport{}, err
212		}
213		return report, nil
214	}
